	/**
	 * 保持するコンテナのListを返します。
	 *
	 * @return コンテナのList
	 */
	public List<MCContainer> getContainers(){
		List<MCContainer> ret = super.getContainers();
		if(!MCCollectionUtil.contains(ret, getCndR())) ret.add(getCndR());
		if(!MCCollectionUtil.contains(ret, getCopyCndR())) ret.add(getCopyCndR());
		if(!MCCollectionUtil.contains(ret, getDispRslt1L())) ret.add(getDispRslt1L());
		if(!MCCollectionUtil.contains(ret, getRslt1L())) ret.add(getRslt1L());
		if(!MCCollectionUtil.contains(ret, getRslt2HdrR())) ret.add(getRslt2HdrR());
		if(!MCCollectionUtil.contains(ret, getRslt2L())) ret.add(getRslt2L());
		if(!MCCollectionUtil.contains(ret, getRslt3L())) ret.add(getRslt3L());
		if(!MCCollectionUtil.contains(ret, getRslt4L())) ret.add(getRslt4L());
		if(!MCCollectionUtil.contains(ret, getRslt4BtnR())) ret.add(getRslt4BtnR());
		if(!MCCollectionUtil.contains(ret, getRslt5L())) ret.add(getRslt5L());
		if(!MCCollectionUtil.contains(ret, getCsvL())) ret.add(getCsvL());
		return ret;
	}

	/**
	 * コンテナに対応したブロックのIDを返します。
	 *
	 * 引数のコンテナに対応するブロックがない場合にはnullを返します。<br>
	 * 引数がnullの場合にはnullを返します。<br>
	 *
	 * @return ブロックID
	 */
	public String getBlockId(MCContainer aCnt){
		if(aCnt == null) return null;
		if(aCnt == getCndR()) return "Cnd";
		if(aCnt == getCopyCndR()) return "CopyCnd";
		if(aCnt == getDispRslt1L()) return "DispRslt1";
		if(aCnt == getRslt1L()) return "Rslt1";
		if(aCnt == getRslt2HdrR()) return "Rslt2Hdr";
		if(aCnt == getRslt2L()) return "Rslt2";
		if(aCnt == getRslt3L()) return "Rslt3";
		if(aCnt == getRslt4L()) return "Rslt4";
		if(aCnt == getRslt4BtnR()) return "Rslt4Btn";
		if(aCnt == getRslt5L()) return "Rslt5";
		if(aCnt == getCsvL()) return "Csv";
		return super.getBlockId(aCnt);
	}

	/**
	 * ブロックIDに対応したコンテナを返します。
	 *
	 * 引数のブロックIDに対応するブロックがない場合にはnullを返します。<br>
	 * 引数がnullの場合にはnullを返します。<br>
	 *
	 * @return コンテナ
	 */
	public MCContainer getContainer(String bId){
		if(bId == null) return null;
		if(bId.equals("Cnd")) return getCndR();
		if(bId.equals("CopyCnd")) return getCopyCndR();
		if(bId.equals("DispRslt1")) return getDispRslt1L();
		if(bId.equals("Rslt1")) return getRslt1L();
		if(bId.equals("Rslt2Hdr")) return getRslt2HdrR();
		if(bId.equals("Rslt2")) return getRslt2L();
		if(bId.equals("Rslt3")) return getRslt3L();
		if(bId.equals("Rslt4")) return getRslt4L();
		if(bId.equals("Rslt4Btn")) return getRslt4BtnR();
		if(bId.equals("Rslt5")) return getRslt5L();
		if(bId.equals("Csv")) return getCsvL();
		return super.getContainer(bId);
	}

