	/**
	 * リストを保持する画面部品のリストを返します。
	 */
	public MCList getList(MCEventBeans combo, MCRow row, MCEventInfo info) {
		MCList list = super.getList(combo, row, info);
		if(list != null) return list;
		if(combo == Cnd_dmnd_loc_cd) return getCnd_dmnd_loc_cd(row, info);
		if(combo == Cnd_site_cd) return getCnd_site_cd(row, info);
		if(combo == Cnd_wg_cd) return getCnd_wg_cd(row, info);
		if(combo == Cnd_lg_grp_cd) return getCnd_lg_grp_cd(row, info);
		if(combo == Cnd_loc_grp_cd) return getCnd_loc_grp_cd(row, info);
		if(combo == Cnd_itm_p_PPanel.Itm_itm_cd) return getCnd_itm_p_PPanel_Itm_itm_cd(row, info);
		if(combo == Cnd_itm_p_PPanel.Itm_itm_sub1) return getCnd_itm_p_PPanel_Itm_itm_sub1(row, info);
		if(combo == Cnd_itm_p_PPanel.Itm_itm_sub2) return getCnd_itm_p_PPanel_Itm_itm_sub2(row, info);
		if(combo == Cnd_itm_p_PPanel.Itm_itm_sub3) return getCnd_itm_p_PPanel_Itm_itm_sub3(row, info);
		if(combo == columnRslt3_strg_loc_cd) return getRslt3_strg_loc_cd(row, info);
		if(combo == columnRslt3_base_unit_cd) return getRslt3_base_unit_cd(row, info);
		if(combo == columnRslt3_mfg_loc_cd) return getRslt3_mfg_loc_cd(row, info);
		if(combo == columnRslt3_sppl_cd) return getRslt3_sppl_cd(row, info);
		if(combo == columnRslt3_rqst_loc_cd) return getRslt3_rqst_loc_cd(row, info);
		if(combo == columnRslt5_dmnd_loc_cd) return getRslt5_dmnd_loc_cd(row, info);
		if(combo == columnRslt5_base_unit_cd) return getRslt5_base_unit_cd(row, info);
		return null;
	}

	/**
	 * ActionPerformedイベントが実行されたときに呼び出されます。
	 *
	 * @param ap ActionPerformedイベントが実行されたGUI部品
	 */
	public void doAPEvent(MCAPBeans ap, MCEventInfo info) {
		super.doAPEvent(ap, info);
		if (ap == Ctrl_ctrl_PPanel.Ope_srch) doCtrl_ctrl_Ope_srch(info);
		else if (ap == RPnl_dwnld) doRPnl_dwnld(info);
		else if (ap == Rslt1Btn_select_all) doRslt1Btn_select_all(info);
		else if (ap == Rslt1Btn_deselect_all) doRslt1Btn_deselect_all(info);
		else if (ap == Rslt2Hdr_openGraph) doRslt2Hdr_openGraph(info);
		else if (ap == Rslt3Btn_radd) doRslt3Btn_radd(info);
		else if (ap == Rslt3Btn_rdel) doRslt3Btn_rdel(info);
		else if (ap == Rslt3Btn_rcopy) doRslt3Btn_rcopy(info);
		else if (ap == Rslt4Btn_rfrct) doRslt4Btn_rfrct(info);
		else if (ap == Rslt4Btn_select_all) doRslt4Btn_select_all(info);
		else if (ap == Rslt4Btn_deselect_all) doRslt4Btn_deselect_all(info);
		else if (ap == Btn_open_MSBCP0150) doBtn_open_MSBCP0150(info);
		else if (ap == Btn_out_file) doBtn_out_file(info);
		else if (ap == Btn_in_file) doBtn_in_file(info);
		else if (ap == Btn_upd) doBtn_upd(info);
	}

